import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.CWdVbaJB.js";const u=JSON.parse('{"title":"Environment Variables","description":"","frontmatter":{"title":"Environment Variables"},"headers":[],"relativePath":"self-hosting/environment.md","filePath":"self-hosting/environment.md"}'),r={name:"self-hosting/environment.md"};function i(n,t,c,l,h,s){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h1><p>All configuration is through environment variables. Copy <code>.env.example</code> to <code>.env</code> and adjust as needed.</p><h2 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>DATABASE_URL</code></td><td><code>postgresql://postgres:postgres@db:5432/shavira</code></td><td>PostgreSQL connection string</td></tr></tbody></table><h2 id="server" tabindex="-1">Server <a class="header-anchor" href="#server" aria-label="Permalink to &quot;Server&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>PORT</code></td><td><code>4000</code></td><td>API server port</td></tr><tr><td><code>NODE_ENV</code></td><td><code>development</code></td><td>Node environment</td></tr><tr><td><code>VITE_API_BASE</code></td><td><code>http://localhost:4000</code></td><td>API URL for the web frontend</td></tr></tbody></table><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>JWT_SECRET</code></td><td>(required)</td><td>Secret for signing JWT tokens. Use a random 64+ character string</td></tr><tr><td><code>REQUIRE_EMAIL_VERIFICATION</code></td><td><code>false</code></td><td>Require email verification before login</td></tr><tr><td><code>BOOTSTRAP_DEFAULT_ADMIN</code></td><td><code>true</code></td><td>Create default admin user on first start</td></tr></tbody></table><h2 id="email" tabindex="-1">Email <a class="header-anchor" href="#email" aria-label="Permalink to &quot;Email&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>EMAIL_TRANSPORT</code></td><td><code>noop</code></td><td>Email transport: <code>noop</code>, <code>smtp</code>, or <code>ses</code></td></tr><tr><td><code>SMTP_HOST</code></td><td>—</td><td>SMTP server hostname</td></tr><tr><td><code>SMTP_PORT</code></td><td><code>587</code></td><td>SMTP server port</td></tr><tr><td><code>SMTP_USER</code></td><td>—</td><td>SMTP username</td></tr><tr><td><code>SMTP_PASS</code></td><td>—</td><td>SMTP password</td></tr><tr><td><code>EMAIL_FROM</code></td><td><code>noreply@shavira.local</code></td><td>Sender email address</td></tr></tbody></table><h2 id="google-oauth" tabindex="-1">Google OAuth <a class="header-anchor" href="#google-oauth" aria-label="Permalink to &quot;Google OAuth&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>GOOGLE_CLIENT_ID</code></td><td>—</td><td>Google OAuth client ID</td></tr><tr><td><code>GOOGLE_CLIENT_SECRET</code></td><td>—</td><td>Google OAuth client secret</td></tr><tr><td><code>GOOGLE_CALLBACK_URL</code></td><td>—</td><td>OAuth callback URL</td></tr></tbody></table><h2 id="model-routing" tabindex="-1">Model Routing <a class="header-anchor" href="#model-routing" aria-label="Permalink to &quot;Model Routing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>LOCAL_MODEL_ENDPOINT</code></td><td>—</td><td>Local model server URL (Ollama/vLLM)</td></tr><tr><td><code>LOCAL_MODEL_NAME</code></td><td>—</td><td>Default local model name</td></tr></tbody></table><h2 id="pricing-sync" tabindex="-1">Pricing Sync <a class="header-anchor" href="#pricing-sync" aria-label="Permalink to &quot;Pricing Sync&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>PRICING_SYNC_INTERVAL_MS</code></td><td><code>86400000</code> (24h)</td><td>How often the pricing sync runs (milliseconds)</td></tr><tr><td><code>SLACK_WEBHOOK_URL</code></td><td>—</td><td>Slack webhook for &gt;20% price change alerts</td></tr><tr><td><code>ALERT_EMAIL</code></td><td>—</td><td>Email address for &gt;20% price change alerts</td></tr></tbody></table><p>Model pricing is synced automatically from the <a href="https://github.com/BerriAI/litellm" target="_blank" rel="noreferrer">LiteLLM catalog</a>. See <a href="/shavira-docs/platform/pricing.html">Pricing &amp; Costs</a> for details.</p><h2 id="security-notes" tabindex="-1">Security Notes <a class="header-anchor" href="#security-notes" aria-label="Permalink to &quot;Security Notes&quot;">​</a></h2><ul><li>Never commit <code>.env</code> files to version control</li><li>Use strong, unique values for <code>JWT_SECRET</code></li><li>In production, use a secrets manager (AWS SSM, Vault, etc.) instead of <code>.env</code> files</li><li>Rotate API keys periodically</li></ul>',19)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
